insert into public.code_clauses (code_document_id, section_no, title, summary, limits) select id, '425.4.2', 'Development of deformed bars in tension', 'ld is taken from the general equation ld = [fy/(1.1λ√f''c)]·[ψtψeψs/((cb+Ktr)/db)]·db or the simplified table, and is never less than 300 mm. (cb+Ktr)/db is capped at 2.5 and ψt·ψe at 1.7.', '{"aci_equivalent":"ACI 318-14 §25.4.2"}'::jsonb from public.code_documents where short_name = 'NSCP' and edition = '2015 (7th ed.)';
insert into public.code_clauses (code_document_id, section_no, title, summary, limits) select id, '425.4.3', 'Development of standard hooks in tension', 'ldh = (0.24 fy ψe ψc ψr / (λ√f''c))·db, not less than 8db or 150 mm. Reductions apply for side cover (ψc = 0.7) and confining ties (ψr = 0.8) on bars 36 mm and smaller.', '{"aci_equivalent":"ACI 318-14 §25.4.3"}'::jsonb from public.code_documents where short_name = 'NSCP' and edition = '2015 (7th ed.)';
insert into public.code_clauses (code_document_id, section_no, title, summary, limits) select id, '422.2', 'Design assumptions for flexure and axial strength', 'Plane sections remain plane; max concrete strain 0.003; equivalent rectangular stress block of 0.85f''c over depth a = β1·c, where β1 = 0.85 for f''c ≤ 28 MPa, reducing by 0.05 per 7 MPa to a minimum of 0.65.', '{"aci_equivalent":"ACI 318-14 §22.2"}'::jsonb from public.code_documents where short_name = 'NSCP' and edition = '2015 (7th ed.)';
insert into public.code_clauses (code_document_id, section_no, title, summary, limits) select id, '421.2', 'Strength reduction factors φ', 'φ = 0.90 for tension-controlled sections (εt ≥ 0.005), 0.65 tied / 0.75 spiral for compression-controlled, with linear transition in between. Shear φ = 0.75.', '{"aci_equivalent":"ACI 318-14 §21.2"}'::jsonb from public.code_documents where short_name = 'NSCP' and edition = '2015 (7th ed.)';
insert into public.code_clauses (code_document_id, section_no, title, summary, limits) select id, '409.6.1', 'Minimum flexural reinforcement in beams', 'As,min is the larger of 0.25√f''c/fy·bw·d and 1.4/fy·bw·d, unless the provided As is at least 4/3 of that required by analysis.', '{"aci_equivalent":"ACI 318-14 §9.6.1"}'::jsonb from public.code_documents where short_name = 'NSCP' and edition = '2015 (7th ed.)';
insert into public.code_clauses (code_document_id, section_no, title, summary, limits) select id, '407.3.1', 'Minimum thickness of one-way slabs', 'For solid nonprestressed one-way slabs not supporting partitions likely to be damaged: ℓ/20 simply supported, ℓ/24 one end continuous, ℓ/28 both ends continuous, ℓ/10 cantilever (fy = 420 MPa; multiply by 0.4 + fy/700 for other fy).', '{"aci_equivalent":"ACI 318-14 §7.3.1"}'::jsonb from public.code_documents where short_name = 'NSCP' and edition = '2015 (7th ed.)';
insert into public.code_clauses (code_document_id, section_no, title, summary, limits) select id, '424.4.3', 'Shrinkage and temperature reinforcement', 'Minimum ratio of gross area: 0.0020 for Grade 280/350 deformed bars, 0.0018 for Grade 420, and 0.0018×420/fy (≥ 0.0014) for higher grades. Spacing ≤ 5h and ≤ 450 mm.', '{"aci_equivalent":"ACI 318-14 §24.4.3"}'::jsonb from public.code_documents where short_name = 'NSCP' and edition = '2015 (7th ed.)';
insert into public.code_clauses (code_document_id, section_no, title, summary, limits) select id, '422.4.2', 'Maximum axial strength', 'Po = 0.85f''c(Ag − Ast) + fyAst. Maximum nominal axial strength is 0.80Po for tied and 0.85Po for spiral columns.', '{"aci_equivalent":"ACI 318-14 §22.4.2"}'::jsonb from public.code_documents where short_name = 'NSCP' and edition = '2015 (7th ed.)';
insert into public.code_clauses (code_document_id, section_no, title, summary, limits) select id, '410.6.1', 'Minimum and maximum longitudinal reinforcement in columns', 'Longitudinal steel area is between 0.01Ag and 0.08Ag. Minimum 4 bars for rectangular/circular tied, 6 for spiral.', '{"aci_equivalent":"ACI 318-14 §10.6.1"}'::jsonb from public.code_documents where short_name = 'NSCP' and edition = '2015 (7th ed.)';
insert into public.entries (id, module, title, slug, specialization_id, summary, status) select 'd74fff92-8b7c-45c7-8173-110e5d7f0fdb', 'tool', 'Development length & tension lap splice', 'tool-development-length-and-lap-splice', id, 'ld for straight deformed bars in tension, with Class A/B lap lengths.', 'review' from public.specializations where slug = 'concrete';
insert into public.entry_revisions (id, entry_id, rev_no, body, change_note, code_edition) values ('332f96cc-fa41-4bbd-8b47-48a1ea76f63b', 'd74fff92-8b7c-45c7-8173-110e5d7f0fdb', 1, '{"sections":[{"kind":"text","heading":"When to use","text":"Checking lap lengths on rebar schedules and bar bending lists, and development past critical sections."},{"kind":"avoid","heading":"Limitations","items":["Straight deformed bars in tension only (compression ld is different)","Ktr = 0 is conservative; enter Ktr only if transverse steel is detailed","Bundled bars need the bundle factor (not included)"]},{"kind":"text","heading":"Note","text":"Equations follow NSCP 2015 Ch. 4 (= ACI 318-14). Verify against your NSCP copy before marking reviewed."}]}'::jsonb, 'Initial tool (v0.3.0): needs review', 'NSCP 2015');
insert into public.tools (entry_id, kind, calc_key, input_schema, output_schema, hand_check) values ('d74fff92-8b7c-45c7-8173-110e5d7f0fdb', 'calculator', 'dev-length-tension', '{"fields":[{"key":"db","label":"Bar diameter db","unit":"mm","type":"number","default":20,"min":6},{"key":"fy","label":"Steel yield strength fy","unit":"MPa","type":"number","default":415},{"key":"fc","label":"Concrete strength f''c","unit":"MPa","type":"number","default":21},{"type":"select","key":"lambda","label":"Concrete type (λ)","default":"1","options":[{"value":"1","label":"Normal weight (λ = 1.0)"},{"value":"0.75","label":"Lightweight (λ = 0.75)"}]},{"key":"top","label":"Casting position (ψt)","type":"select","default":"1","options":[{"value":"1","label":"Other bars (ψt = 1.0)"},{"value":"1.3","label":"Top bars: >300 mm fresh concrete below (ψt = 1.3)"}]},{"key":"psie","label":"Coating (ψe)","type":"select","default":"1","options":[{"value":"1","label":"Uncoated / galvanized (1.0)"},{"value":"1.2","label":"Epoxy, other cases (1.2)"},{"value":"1.5","label":"Epoxy, cover < 3db or spacing < 6db (1.5)"}]},{"key":"cb","label":"cb: smaller of cover to bar center or ½ c/c spacing","unit":"mm","type":"number","default":60,"help":"e.g. 40 cover + 10 stirrup + db/2"},{"key":"ktr","label":"Ktr: transverse reinforcement index (0 = conservative)","unit":"mm","type":"number","default":0}]}'::jsonb, '{"results":[{"label":"Development length ld","unit":"mm"},{"label":"Class A lap (1.0 ld)","unit":"mm"},{"label":"Class B lap (1.3 ld), the usual case","unit":"mm"},{"label":"ld / db","unit":null}]}'::jsonb, '{"inputs":{"db":20,"fy":415,"fc":21,"lambda":"1","top":"1","psie":"1","cb":60,"ktr":0},"results":[{"label":"Development length ld","value":659,"unit":"mm"},{"label":"Class A lap (1.0 ld)","value":659,"unit":"mm"},{"label":"Class B lap (1.3 ld), the usual case","value":856,"unit":"mm"},{"label":"ld / db","value":32.9}],"steps":["ψs = 1 (db > 19 mm); ψt·ψe = 1; λ = 1","√f''c = √21 = 4.583 MPa","(cb + Ktr)/db = (60 + 0)/20 = 3 → use 2.5","ld = [fy / (1.1 λ √f''c)] × [ψt ψe ψs / ((cb+Ktr)/db)] × db","ld = [415 / (1.1 × 1 × 4.583)] × [1 × 1 / 2.5] × 20 = 658.6 mm","ld = max(658.6, 300) = 658.6 mm","Class B lap = 1.3 × 658.6 = 856.2 mm (≥ 300 mm)"],"verified_by":"Cross-checked by independent hand calculation (v0.3.0 build)","note":"Re-run the inputs above. Results must match before trusting a code change."}'::jsonb);
