insert into public.entries (id, module, title, slug, specialization_id, summary, status) select 'bd491a5d-4395-47a6-8bca-336ac93388c9', 'tool', 'Development length of standard hooks in tension', 'tool-hooked-bar-development-length', id, 'ldh for 90° and 180° standard hooks in tension.', 'review' from public.specializations where slug = 'concrete';
insert into public.entry_revisions (id, entry_id, rev_no, body, change_note, code_edition) values ('53865d0c-0f66-43b8-a793-c637f44bef7e', 'bd491a5d-4395-47a6-8bca-336ac93388c9', 1, '{"sections":[{"kind":"text","heading":"When to use","text":"Beam bars terminating in exterior columns, cantilever anchorage, footing dowels."},{"kind":"avoid","heading":"Limitations","items":["Tension hooks only; hooks are not effective in compression","Check joint dimensions can fit ldh plus cover"]},{"kind":"text","heading":"Note","text":"Equations follow NSCP 2015 Ch. 4 (= ACI 318-14). Verify against your NSCP copy before marking reviewed."}]}'::jsonb, 'Initial tool (v0.3.0): needs review', 'NSCP 2015');
insert into public.tools (entry_id, kind, calc_key, input_schema, output_schema, hand_check) values ('bd491a5d-4395-47a6-8bca-336ac93388c9', 'calculator', 'dev-length-hook', '{"fields":[{"key":"db","label":"Bar diameter db","unit":"mm","type":"number","default":20},{"key":"fy","label":"Steel yield strength fy","unit":"MPa","type":"number","default":415},{"key":"fc","label":"Concrete strength f''c","unit":"MPa","type":"number","default":21},{"type":"select","key":"lambda","label":"Concrete type (λ)","default":"1","options":[{"value":"1","label":"Normal weight (λ = 1.0)"},{"value":"0.75","label":"Lightweight (λ = 0.75)"}]},{"key":"psie","label":"Coating (ψe)","type":"select","default":"1","options":[{"value":"1","label":"Uncoated (1.0)"},{"value":"1.2","label":"Epoxy-coated (1.2)"}]},{"key":"psic","label":"Cover (ψc)","type":"select","default":"1","options":[{"value":"1","label":"Other (1.0)"},{"value":"0.7","label":"≤ 36 mm bar, side cover ≥ 65 mm (and 50 mm beyond 90° hook) (0.7)"}]},{"key":"psir","label":"Confining ties (ψr)","type":"select","default":"1","options":[{"value":"1","label":"Other (1.0)"},{"value":"0.8","label":"≤ 36 mm bar enclosed by ties at ≤ 3db (0.8)"}]}]}'::jsonb, '{"results":[{"label":"Hook development length ldh","unit":"mm"},{"label":"Minimum (8db, 150 mm)","unit":"mm"},{"label":"Tail: 90° hook = 12db","unit":"mm"},{"label":"Tail: 180° hook = max(4db, 65)","unit":"mm"}]}'::jsonb, '{"inputs":{"db":20,"fy":415,"fc":21,"lambda":"1","psie":"1","psic":"1","psir":"1"},"results":[{"label":"Hook development length ldh","value":435,"unit":"mm"},{"label":"Minimum (8db, 150 mm)","value":160,"unit":"mm"},{"label":"Tail: 90° hook = 12db","value":240,"unit":"mm"},{"label":"Tail: 180° hook = max(4db, 65)","value":80,"unit":"mm"}],"steps":["√f''c = 4.583 MPa","ldh = (0.24 fy ψe ψc ψr / (λ √f''c)) × db","ldh = (0.24 × 415 × 1 × 1 × 1 / (1 × 4.583)) × 20 = 434.7 mm","ldh = max(434.7, 8 × 20, 150) = 434.7 mm"],"verified_by":"Cross-checked by independent hand calculation (v0.3.0 build)","note":"Re-run the inputs above. Results must match before trusting a code change."}'::jsonb);
