insert into public.entries (id, module, title, slug, specialization_id, summary, status) select 'e81ece1e-d55a-4351-8ad4-4c94acdf6865', 'tool', 'Rectangular beam: flexural capacity φMn (singly reinforced)', 'tool-beam-flexural-capacity', id, 'φMn of a singly reinforced rectangular section, with φ and As,min checks.', 'review' from public.specializations where slug = 'concrete';
insert into public.entry_revisions (id, entry_id, rev_no, body, change_note, code_edition) values ('e0ef93db-5c7e-4fdf-b9f9-c179a4b5292c', 'e81ece1e-d55a-4351-8ad4-4c94acdf6865', 1, '{"sections":[{"kind":"text","heading":"When to use","text":"Checking an existing or shop-drawing beam, or a substitution of bar sizes."},{"kind":"avoid","heading":"Limitations","items":["Singly reinforced rectangular sections; T-beams and compression steel not included","Single layer of tension bars assumed at depth d"]},{"kind":"text","heading":"Note","text":"Equations follow NSCP 2015 Ch. 4 (= ACI 318-14). Verify against your NSCP copy before marking reviewed."}]}'::jsonb, 'Initial tool (v0.3.0): needs review', 'NSCP 2015');
insert into public.tools (entry_id, kind, calc_key, input_schema, output_schema, hand_check) values ('e81ece1e-d55a-4351-8ad4-4c94acdf6865', 'calculator', 'beam-flexure-analysis', '{"fields":[{"key":"b","label":"Width b","unit":"mm","type":"number","default":300},{"key":"d","label":"Effective depth d","unit":"mm","type":"number","default":450},{"key":"nbars","label":"Number of tension bars","type":"number","default":4,"min":1},{"key":"db","label":"Bar diameter","unit":"mm","type":"number","default":20},{"key":"fc","label":"f''c","unit":"MPa","type":"number","default":21},{"key":"fy","label":"fy","unit":"MPa","type":"number","default":415}]}'::jsonb, '{"results":[{"label":"φMn","unit":"kN·m"},{"label":"Mn","unit":"kN·m"},{"label":"φ","unit":null},{"label":"As provided","unit":"mm²"},{"label":"a","unit":"mm"},{"label":"c","unit":"mm"},{"label":"εt","unit":null}]}'::jsonb, '{"inputs":{"b":300,"d":450,"nbars":4,"db":20,"fc":21,"fy":415},"results":[{"label":"φMn","value":188.4,"unit":"kN·m"},{"label":"Mn","value":209.3,"unit":"kN·m"},{"label":"φ","value":0.9},{"label":"As provided","value":1256.6,"unit":"mm²"},{"label":"a","value":97.4,"unit":"mm"},{"label":"c","value":114.6,"unit":"mm"},{"label":"εt","value":0.00878}],"steps":["As = 4 × π(20)²/4 = 1256.6 mm²","β1 = 0.85","a = As·fy / (0.85·f''c·b) = 1256.6 × 415 / (0.85 × 21 × 300) = 97.39 mm","c = a/β1 = 114.57 mm","εt = 0.003 (d − c)/c = 0.003 × (450 − 114.57) / 114.57 = 0.00878 → φ = 0.9","Mn = As·fy·(d − a/2) = 1256.6 × 415 × (450 − 48.69) = 209.28 kN·m","φMn = 0.9 × 209.28 = 188.35 kN·m"],"verified_by":"Cross-checked by independent hand calculation (v0.3.0 build)","note":"Re-run the inputs above. Results must match before trusting a code change."}'::jsonb);
