insert into public.entries (id, module, title, slug, specialization_id, summary, status) select 'a9da6b6f-afd5-40e2-9ef1-573b2c8530ee', 'tool', 'Rectangular beam: required tension steel for Mu', 'tool-beam-required-steel', id, 'Required tension steel and bar count for a given Mu.', 'review' from public.specializations where slug = 'concrete';
insert into public.entry_revisions (id, entry_id, rev_no, body, change_note, code_edition) values ('079e3c40-fd8b-490a-b4e5-1fd5b0c59efb', 'a9da6b6f-afd5-40e2-9ef1-573b2c8530ee', 1, '{"sections":[{"kind":"text","heading":"When to use","text":"Quick sizing of beam bars during estimating or value engineering."},{"kind":"avoid","heading":"Limitations","items":["Assumes φ = 0.9 then re-checks with the bars provided","Does not check clear spacing; use the spacing card","Shear, deflection and crack control are separate checks"]},{"kind":"text","heading":"Note","text":"Equations follow NSCP 2015 Ch. 4 (= ACI 318-14). Verify against your NSCP copy before marking reviewed."}]}'::jsonb, 'Initial tool (v0.3.0): needs review', 'NSCP 2015');
insert into public.tools (entry_id, kind, calc_key, input_schema, output_schema, hand_check) values ('a9da6b6f-afd5-40e2-9ef1-573b2c8530ee', 'calculator', 'beam-flexure-design', '{"fields":[{"key":"mu","label":"Factored moment Mu","unit":"kN·m","type":"number","default":150},{"key":"b","label":"Width b","unit":"mm","type":"number","default":300},{"key":"d","label":"Effective depth d","unit":"mm","type":"number","default":450},{"key":"fc","label":"f''c","unit":"MPa","type":"number","default":21},{"key":"fy","label":"fy","unit":"MPa","type":"number","default":415},{"key":"db","label":"Bar diameter to use","unit":"mm","type":"number","default":20}]}'::jsonb, '{"results":[{"label":"Required As","unit":"mm²"},{"label":"Use 4 – 20 mm bars","unit":"mm²"},{"label":"ρ required","unit":null},{"label":"φMn with bars provided","unit":"kN·m"}]}'::jsonb, '{"inputs":{"mu":150,"b":300,"d":450,"fc":21,"fy":415,"db":20},"results":[{"label":"Required As","value":974.2,"unit":"mm²"},{"label":"Use 4 – 20 mm bars","value":1256.6,"unit":"mm²"},{"label":"ρ required","value":0.00722},{"label":"φMn with bars provided","value":188.4,"unit":"kN·m"}],"steps":["Rn = Mu/(φ b d²) = 150×10⁶ / (0.9 × 300 × 450²) = 2.7435 MPa","ρ = (0.85f''c/fy)[1 − √(1 − 2Rn/(0.85f''c))] = 0.007216","As = ρbd = 974.2 mm²; As,min = 455.4 mm² → As = 974.2 mm²","n = As / (π20²/4) = 3.1 → 4 bars = 1256.6 mm²","Check: a = 97.39 mm, c = 114.57 mm, εt = 0.00878, φ = 0.9, φMn = 188.35 kN·m"],"verified_by":"Cross-checked by independent hand calculation (v0.3.0 build)","note":"Re-run the inputs above. Results must match before trusting a code change."}'::jsonb);
