insert into public.entries (id, module, title, slug, specialization_id, summary, status) select '05259934-d3c8-4f85-9411-7ca7f43b8a1b', 'tool', 'One-way slab: minimum thickness & temperature bars', 'tool-one-way-slab-thickness-and-temperature-bars', id, 'Minimum slab thickness without deflection calcs, plus temperature bar spacing.', 'review' from public.specializations where slug = 'concrete';
insert into public.entry_revisions (id, entry_id, rev_no, body, change_note, code_edition) values ('c21fc911-97a9-4bdf-ba80-15690432b2e6', '05259934-d3c8-4f85-9411-7ca7f43b8a1b', 1, '{"sections":[{"kind":"text","heading":"When to use","text":"Early sizing of one-way slabs and checking temperature bars on plans."},{"kind":"avoid","heading":"Limitations","items":["Normal-weight concrete, members not supporting damage-prone partitions","Main flexural steel is a separate design"]},{"kind":"text","heading":"Note","text":"Equations follow NSCP 2015 Ch. 4 (= ACI 318-14). Verify against your NSCP copy before marking reviewed."}]}'::jsonb, 'Initial tool (v0.3.0): needs review', 'NSCP 2015');
insert into public.tools (entry_id, kind, calc_key, input_schema, output_schema, hand_check) values ('05259934-d3c8-4f85-9411-7ca7f43b8a1b', 'calculator', 'one-way-slab-basic', '{"fields":[{"key":"L","label":"Span length ℓ","unit":"mm","type":"number","default":3000},{"key":"support","label":"Support condition","type":"select","default":"both","options":[{"value":"simple","label":"Simply supported (ℓ/20)"},{"value":"one","label":"One end continuous (ℓ/24)"},{"value":"both","label":"Both ends continuous (ℓ/28)"},{"value":"cantilever","label":"Cantilever (ℓ/10)"}]},{"key":"fy","label":"fy","unit":"MPa","type":"number","default":415},{"key":"h","label":"Slab thickness provided h","unit":"mm","type":"number","default":125},{"key":"db","label":"Temperature bar diameter","unit":"mm","type":"number","default":10}]}'::jsonb, '{"results":[{"label":"Minimum thickness hmin","unit":"mm"},{"label":"Temperature steel As","unit":"mm²/m"},{"label":"Use 10 mm bars @","unit":"mm o.c."},{"label":"Max spacing min(5h, 450)","unit":"mm"}]}'::jsonb, '{"inputs":{"L":3000,"support":"both","fy":415,"h":125,"db":10},"results":[{"label":"Minimum thickness hmin","value":106,"unit":"mm"},{"label":"Temperature steel As","value":225,"unit":"mm²/m"},{"label":"Use 10 mm bars @","value":340,"unit":"mm o.c."},{"label":"Max spacing min(5h, 450)","value":450,"unit":"mm"}],"steps":["hmin = ℓ/28 × (0.4 + fy/700) = 3000/28 × 0.9929 = 106.4 mm","ρ(temp) = 0.0018 (Grade 415/420)","As = ρ × 1000 × h = 0.0018 × 1000 × 125 = 225 mm²/m","s = 1000 × Ab / As = 1000 × 78.54 / 225 = 349.1 mm; max 450 mm → use 340 mm"],"verified_by":"Cross-checked by independent hand calculation (v0.3.0 build)","note":"Re-run the inputs above. Results must match before trusting a code change."}'::jsonb);
