insert into public.entry_revisions (id, entry_id, rev_no, body, change_note, code_edition) values ('49dc379c-0676-46c1-8863-d4eef6b54965', '22723c64-4aae-489b-82d3-46b3977ca1df', 1, '{"sections":[{"kind":"text","heading":"When to use","text":"Quick axial check of short columns, or comparing column sizes during estimating."},{"kind":"avoid","heading":"Limitations","items":["Concentric axial load only, no moment or slenderness","Use an interaction diagram (coming later) for Pu + Mu"]},{"kind":"text","heading":"Note","text":"Equations follow NSCP 2015 Ch. 4 (= ACI 318-14). Verify against your NSCP copy before marking reviewed."}]}'::jsonb, 'Initial tool (v0.3.0): needs review', 'NSCP 2015');
insert into public.tools (entry_id, kind, calc_key, input_schema, output_schema, hand_check) values ('22723c64-4aae-489b-82d3-46b3977ca1df', 'calculator', 'column-axial-max', '{"fields":[{"key":"type","label":"Transverse reinforcement","type":"select","default":"tied","options":[{"value":"tied","label":"Tied (φ = 0.65, 0.80 Po)"},{"value":"spiral","label":"Spiral (φ = 0.75, 0.85 Po)"}]},{"key":"b","label":"Width b","unit":"mm","type":"number","default":400},{"key":"h","label":"Depth h","unit":"mm","type":"number","default":400},{"key":"nbars","label":"Number of bars","type":"number","default":8},{"key":"db","label":"Bar diameter","unit":"mm","type":"number","default":20},{"key":"fc","label":"f''c","unit":"MPa","type":"number","default":28},{"key":"fy","label":"fy","unit":"MPa","type":"number","default":415}]}'::jsonb, '{"results":[{"label":"φPn,max","unit":"kN"},{"label":"Po","unit":"kN"},{"label":"Ast","unit":"mm²"},{"label":"ρg","unit":null}]}'::jsonb, '{"inputs":{"type":"tied","b":400,"h":400,"nbars":8,"db":20,"fc":28,"fy":415},"results":[{"label":"φPn,max","value":2491.4,"unit":"kN"},{"label":"Po","value":4791.2,"unit":"kN"},{"label":"Ast","value":2513.3,"unit":"mm²"},{"label":"ρg","value":"1.57%"}],"steps":["Ag = 400 × 400 = 160000 mm²; Ast = 8 × π20²/4 = 2513.3 mm²","Po = 0.85 f''c (Ag − Ast) + fy Ast = 0.85 × 28 × 157486.7 + 415 × 2513.3 = 4791.2 kN","φPn,max = 0.65 × 0.8 × 4791.2 = 2491.4 kN"],"verified_by":"Cross-checked by independent hand calculation (v0.3.0 build)","note":"Re-run the inputs above. Results must match before trusting a code change."}'::jsonb);
