insert into public.releases (version, batch_name, notes_md, released_at) values ('v0.3.0','Concrete Tools + Codes index', E'- 6 concrete calculators: development length & lap splice, hooked bars, beam φMn, beam required As, one-way slab thickness & temperature bars, column φPn,max\n- Every tool shows step-by-step substitutions and a recorded hand-check example\n- Codes page: browsable NSCP 2015 clause index (20 clauses) linked to the cards and tools that cite them\n- Tools seeded as review drafts: publish after checking', now());
